<?php
declare(strict_types=1);require_once dirname(__DIR__).'/config/bootstrap.php';require_once dirname(__DIR__).'/backend/repositories/CmsRepository.php';require_once dirname(__DIR__).'/includes/helpers.php';
header('Content-Type: application/xml; charset=utf-8');header('Cache-Control: public, max-age=300');$base=roomshift_base_url();$items=[];
foreach(['index.php','services.php','service-areas.php','how-it-works.php','faq.php','contact.php','quote.php'] as $path)$items[]=['url'=>$base.'/'.$path,'modified'=>date('Y-m-d')];
try{$repo=new CmsRepository(roomshift_db());foreach([['services','service.php'],['areas','service-area.php'],['pages','page.php']] as [$kind,$path]){$page=1;do{$data=match($kind){'services'=>$repo->listServices(['page'=>$page,'limit'=>100]),'areas'=>$repo->listServiceAreas(['page'=>$page,'limit'=>100]),default=>$repo->listPublishedPages(['page'=>$page,'limit'=>100])};foreach($data['items'] as $row){$url=$base.'/'.$path.'?slug='.rawurlencode($row['slug']);$items[]=['url'=>$row['canonical_url']?:$url,'modified'=>isset($row['updated_at'])?date('Y-m-d',strtotime($row['updated_at'])):date('Y-m-d')];}$page++;}while($page<=(int)$data['pagination']['pages']);}}
catch(Throwable $error){error_log('[RoomShift sitemap] '.$error->getMessage());http_response_code(503);$items=[];}
echo '<?xml version="1.0" encoding="UTF-8"?>'."\n".'<urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">';foreach($items as $item){echo '<url><loc>'.htmlspecialchars($item['url'],ENT_XML1|ENT_QUOTES,'UTF-8').'</loc><lastmod>'.htmlspecialchars($item['modified'],ENT_XML1,'UTF-8').'</lastmod></url>'; }echo '</urlset>';
